		const animationConfig = getAnimation(animation);

		this.animation = new Animation({ ...animationConfig });
	}

	getCurrentFrame() {
		const { frames } = getAnimation(this.animation.name);
		return `url(${frames[this.animation.currentFrame]}), auto`;
	}
}

